import { useEffect, useState, useRef } from "react";
import { Chart, registerables } from "chart.js";
import { db } from "../../firebase"; 
import { collection, getDocs } from "firebase/firestore";

Chart.register(...registerables);

const CarbonChart = () => {
  const [carbonData, setCarbonData] = useState([]);
  const chartRef = useRef(null);

  useEffect(() => {
    const fetchCarbonData = async () => {
      try {
        const querySnapshot = await getDocs(collection(db, "carbonFootprint"));
        const data = querySnapshot.docs.map((doc) => doc.data().totalCarbon || 0);

        setCarbonData(data);
      } catch (error) {
        console.error("Error fetching carbon data:", error);
      }
    };

    fetchCarbonData();
  }, []);

  useEffect(() => {
    if (carbonData.length === 0 || !chartRef.current) return;

    // Destroy existing chart instance before creating a new one
    if (chartRef.current.chartInstance) {
      chartRef.current.chartInstance.destroy();
    }

    const ctx = chartRef.current.getContext("2d");

    chartRef.current.chartInstance = new Chart(ctx, {
      type: "bar",
      data: {
        labels: ["Jan", "Feb", "Mar", "Apr", "May"], // Customize labels as needed
        datasets: [
          {
            label: "Carbon Footprint (kg CO₂)",
            data: carbonData, // Data from Firebase
            backgroundColor: "rgba(54, 162, 235, 0.6)",
            borderColor: "rgba(54, 162, 235, 1)",
            borderWidth: 1,
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
          },
        },
      },
    });
  }, [carbonData]);

  return <canvas ref={chartRef} />;
};

export default CarbonChart;
